        raise ValueError("payload must be an object")
    required = {"allow", "deny", "baseline", "retest_runs"}
    keys = set(payload)
    missing = required - keys
    if missing:
        raise ValueError(f"missing field: {sorted(missing)[0]}")
    extra = keys - required
    if extra:
        raise ValueError(f"unknown field: {sorted(extra)[0]}")

